// Insert a key-value pair only if key doesn't exist; return whether inserted
bool insert_if_absent(std::map<std::string, int>& m, const std::string& key, int val) {
    auto result = m.insert({key, val});
    return result.second;  // true if insertion took place
}

// Set a key-value pair, creating or overwriting
